/** Read-only stock-policy acquisition on an already opened bank. No learner or new policy. */
import assert from "node:assert/strict";
import { appendFileSync, statSync } from "node:fs";
import { createInterface } from "node:readline";
import { isDeepStrictEqual } from "node:util";
import { gzipSync } from "node:zlib";
import { buildChoice } from "./build-choice";
import { fightNative, hash } from "./native";
import { selectBarrelForecastIntent } from "./sources/common/src/simulation/barrel_forecast_intent_research";
import { permuteRankedDraftSeed } from "./sources/common/src/simulation/ranked_draft_eval";
import { V08_A19_PROFILE_SCHEMA } from "./sources/common/src/ai/versions/v0_8_a19_profile";

assert.equal(V08_A19_PROFILE_SCHEMA, "hoc.v0_8_a19_production_profile.v10");
const [output, labelOutput] = process.argv.slice(2), g = globalThis as any;
let collecting = false, fault: string | undefined;
let pending: any[] = [], labels: any[] = [], actualTurns = 0;
const maximumActorBytes = 64 * 1024 * 1024;
const bytes = (path: string) => { try { return statSync(path).size; } catch { return 0; } };
const append = (path: string, rows: any[]) => {
    if (!rows.length) return;
    const raw = Buffer.from(rows.map(r => JSON.stringify(r)).join("\n") + "\n");
    const compressed = gzipSync(raw, { level: 1 });
    assert(bytes(path) + compressed.length <= maximumActorBytes, "Fixed per-actor output ceiling; no truncation/retry");
    appendFileSync(path, compressed);
};
const publicUnit = (u: any) => ({
    id: u.getId(), name: u.getName(), team: u.getTeam(), cells: structuredClone(u.getCells()),
    hp: u.getCumulativeHp(), alive: u.getAmountAlive(), maxHp: u.getMaxHp(), exp: u.getExp(),
    steps: u.getSteps(), initiative: u.getInitiative(), armor: u.getArmor(), rangeArmor: u.getRangeArmor(),
    shots: u.getRangeShots(), fly: u.canFly(), dead: u.isDead(), attackSelection: u.getAttackTypeSelection(),
    properties: structuredClone(u.getUnitProperties()),
    spells: u.getSpells().map((s: any) => ({ name: s.getName(), remaining: s.getAmount() })),
});
g.__barrelForecastBoundary = (unit: any, context: any, before: any[], cleanup: any[]) => {
    if (!collecting || context.decisionOrigin !== "root") return cleanup;
    try {
        // Eligibility is exactly the frozen projected-policy query, without changing the real context.
        const alternate = selectBarrelForecastIntent(unit, { ...context, decisionOrigin: "rollout" }, before, cleanup);
        if (alternate === cleanup) return cleanup;
        pending.push({
            actualTurn: actualTurns, unitId: unit.getId(), actor: unit.getName(), team: unit.getTeam(),
            lap: context.fightProperties.getCurrentLap(), before: structuredClone(before), cleanup: structuredClone(cleanup),
            publicState: {
                gridType: context.grid.getGridType(), matrix: structuredClone(context.matrix),
                units: [...context.unitsHolder.getAllUnits().values()].map(publicUnit),
                barrels: structuredClone(context.grid.getArtifactBarrels()),
                terrain: structuredClone(context.grid.getScatteredMountainsStanding()),
                upNext: [...context.fightProperties.getUpNextQueueIterable()],
            },
        });
    } catch (error) { fault = String(error); throw error; }
    return cleanup; // Always retain the exact original object, including reference identity.
};
g.__rushTurn = (r: any) => {
    for (const observation of pending) {
        assert.equal(observation.unitId, r.unitId, "Associate observations only with the actual active unit");
        assert.equal(observation.actualTurn, actualTurns);
        const strike = observation.cleanup.find((a: any) => a.type === "obstacle_attack");
        assert(strike);
        const choseSameBarrel = r.chosenDecision.some((a: any) => a.type === "obstacle_attack" &&
            a.attackerId === strike.attackerId && isDeepStrictEqual(a.targetPosition, strike.targetPosition));
        labels.push({ ...observation, rootCallOrdinal: labels.filter(o => o.actualTurn === actualTurns).length,
            labelChoseNativeBarrel: Number(choseSameBarrel),
            exactCleanupChosen: isDeepStrictEqual(r.chosenDecision, observation.cleanup),
            exactPreCleanupChosen: isDeepStrictEqual(r.chosenDecision, observation.before),
            actualRawIncumbent: structuredClone(r.rawIncumbent), chosenDecision: structuredClone(r.chosenDecision),
            rawAndChosenShareArray: r.rawIncumbent === r.chosenDecision,
        });
    }
    pending = []; actualTurns++;
};

for await (const line of createInterface({ input: process.stdin })) {
    const { job, registrationSha256 } = JSON.parse(line);
    collecting = false; fault = undefined; pending = []; labels = []; actualTurns = 0;
    const team = (job.game < 2) === (job.game % 2 === 0) ? 2 : 1;
    const seed = permuteRankedDraftSeed(job.seed + 6 + Number(job.game >= 2));
    const built = buildChoice(job, "current", "current", team);
    assert.equal(hash(built.drafted.config), job.draftConfigSha256[Number(job.game >= 2)]);
    const inputHash = hash({ config: built.opening.config, teams: built.opening.teams, terrain: built.opening.terrain, combatSeed: seed });
    assert.equal(inputHash, job.expectedInputSha256);
    collecting = true;
    let fought: ReturnType<typeof fightNative>;
    try { fought = fightNative(structuredClone(built.opening), seed); }
    finally { collecting = false; }
    assert(!fault, `Observation error was swallowed: ${fault}`);
    assert.equal(pending.length, 0, "No eligible root may lose its actual-turn observation");
    assert.equal(fought.result.endReason, "elimination");
    const score = fought.result.winner === "draw" ? .5 : Number(fought.result.winner === (team === 2 ? "green" : "red"));
    assert.equal(fought.traceSha256, job.expectedTraceSha256);
    assert.equal(score, job.expectedScore);
    const rows = labels.map((o, ordinal) => ({ board: job.board, game: job.game, seed: job.seed,
        sourceProfile: "v10", registrationSha256, inputSha256: inputHash, traceSha256: fought.traceSha256,
        labelId: `${job.board}/${job.game}/${o.actualTurn}/${o.rootCallOrdinal}`, ordinal, ...o }));
    const labelCounts = { clear: rows.filter(o => o.labelChoseNativeBarrel === 1).length, other: rows.filter(o => o.labelChoseNativeBarrel === 0).length };
    // Emit only after all original control checks pass. Seeds/UUIDs/case identities are metadata, not learner inputs.
    append(labelOutput, rows);
    append(output, [{ board: job.board, game: job.game, registrationSha256, inputSha256: inputHash,
        traceSha256: fought.traceSha256, score, actualTurns, labels: rows.length, labelCounts,
        labelsSha256: hash(rows), quality: fought.quality, pureStockOriginalControlPassed: true }]);
    console.log(JSON.stringify({ board: job.board, game: job.game, rows: 1, labels: rows.length, labelCounts, verified: true }));
}

from pathlib import Path
import datetime,json,os,subprocess
p=Path(__file__).resolve().parent
state={'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'controllerPid':os.getpid(),'complete':False,'stage':'starting','errors':[],'noAutomaticRetryOrModelFit':True}
def save():
 state['at']=datetime.datetime.now(datetime.timezone.utc).isoformat()
 temp=p/'barrel-teacher-supervisor-status.tmp';temp.write_text(json.dumps(state,indent=2)+'\n');temp.replace(p/'barrel-teacher-supervisor-status.json')
try:
 for phase in ['preflight','collection']:
  state['stage']=phase;save()
  with(p/f'barrel-teacher-{phase}-controller.log').open('x')as log:
   subprocess.run(['python3','run-barrel-teacher.py',phase],cwd=p,stdin=subprocess.DEVNULL,stdout=log,stderr=subprocess.STDOUT,check=True)
  result=json.loads((p/f'barrel-teacher-{phase}/status.json').read_text());assert result['complete']and not result['errors']and not result['liveWorkerPids']
 state['stage']='collection-complete-awaiting-independent-data-verification';state['complete']=True;save()
except BaseException as error:
 state['errors'].append(repr(error));state['stage']='stopped-needs-inspection';save();raise

import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { isDeepStrictEqual as equal } from "node:util";
import { gunzipSync } from "node:zlib";
const p = import.meta.dir, root = resolve(process.argv[2]);
const json = (path: string) => JSON.parse(readFileSync(path, "utf8"));
const sha = (raw: Buffer | string) => createHash("sha256").update(raw).digest("hex");
const seal = "44d2366afc1bbca1f079b474b22659c716b67b1bb7c79beb646df7bca447d424";
const regRaw = readFileSync(resolve(root, "barrel-teacher-registration.json")); assert.equal(sha(regRaw), seal);
const reg = JSON.parse(regRaw.toString()), sourceRaw = readFileSync(resolve(root, "strength-registration.json"));
assert.equal(sha(sourceRaw), reg.sourceManifestSha256);
for (const f of [...JSON.parse(sourceRaw.toString()).files, ...reg.files]) assert.equal(sha(readFileSync(resolve(root, f.path))), f.sha256);
const stages: any = {};
for (const stage of ["preflight", "collection"]) {
    const path = resolve(root, `barrel-teacher-${stage}`), status = json(resolve(path, "status.json"));
    assert(status.complete && !status.errors.length && !status.liveWorkerPids.length); assert.equal(status.registrationSha256, seal);
    const jobs = json(resolve(root, stage === "preflight" ? "barrel-teacher-preflight-cases.json" : "barrel-teacher-cases.json"));
    const expected = new Map<string, any>(jobs.map((j: any) => [`${j.board}/${j.game}`, j]));
    const controls = new Map<string, any>(), labels = new Map<string, any[]>(), ids = new Set<string>();
    const inventory = [];
    for (const file of readdirSync(path).filter(f => /^worker-\d+(?:-labels)?\.jsonl\.gz$/.test(f)).sort()) {
        const raw = readFileSync(resolve(path, file)); inventory.push({ path: `barrel-teacher-${stage}/${file}`, bytes: raw.length, sha256: sha(raw) });
        for (const line of gunzipSync(raw).toString().trim().split("\n")) {
            const r = JSON.parse(line), key = `${r.board}/${r.game}`, job = expected.get(key); assert(job);
            assert.equal(r.registrationSha256, seal);
            if (file.includes("-labels.")) { const group = labels.get(key) ?? []; group.push(r); labels.set(key, group); }
            else {
                assert(!controls.has(key)); controls.set(key, r);
                assert.equal(r.inputSha256, job.expectedInputSha256); assert.equal(r.traceSha256, job.expectedTraceSha256); assert.equal(r.score, job.expectedScore);
                assert(r.pureStockOriginalControlPassed); assert.equal(r.quality.rejected, 0);
                for (const t of [1, 2]) assert(r.quality.searchUses[t] > 0);
                for (const n of r.quality.neural) for (const k of ["modelErrors", "missingStart", "deadlineAbstentions", "inferenceOverruns"]) assert.equal(n[k], 0);
                for (const w of r.quality.work) for (const k of ["deadlineFallbacks", "degradedDecisions", "circuitSkipped", "circuitWaitArbitrations"]) assert.equal(w[k], 0);
            }
        }
    }
    assert.equal(controls.size, jobs.length); assert.equal(status.fights, jobs.length);
    const counts = { clear: 0, other: 0 }, alternatives = { cleanup: 0, before: 0, third_action: 0 }, families = new Set<number>();
    for (const [key, control] of controls) {
        const group = (labels.get(key) ?? []).sort((a, b) => a.ordinal - b.ordinal), calls = new Map<number, number>();
        assert.equal(group.length, control.labels); assert.equal(sha(JSON.stringify(group)), control.labelsSha256);
        const local = { clear: 0, other: 0 };
        group.forEach((r: any, ordinal: number) => {
            assert.equal(r.ordinal, ordinal); assert.equal(r.sourceProfile, "v10"); assert.equal(r.seed, expected.get(key).seed);
            assert.equal(r.labelId, `${key}/${r.actualTurn}/${r.rootCallOrdinal}`); assert(!ids.has(r.labelId)); ids.add(r.labelId);
            assert(Number.isSafeInteger(r.actualTurn) && r.actualTurn >= 0 && r.actualTurn < control.actualTurns);
            assert.equal(r.rootCallOrdinal, calls.get(r.actualTurn) ?? 0); calls.set(r.actualTurn, r.rootCallOrdinal + 1);
            assert.equal(r.inputSha256, control.inputSha256); assert.equal(r.traceSha256, control.traceSha256);
            const units = r.publicState.units; assert.equal(new Set(units.map((u: any) => u.id)).size, units.length);
            const actors = units.filter((u: any) => u.id === r.unitId); assert.equal(actors.length, 1);
            assert.equal(actors[0].name, r.actor); assert.equal(actors[0].team, r.team); assert.equal(actors[0].dead, false);
            const strikes = r.cleanup.filter((a: any) => a.type === "obstacle_attack"); assert.equal(strikes.length, 1);
            const strike = strikes[0]; assert.equal(strike.attackerId, r.unitId);
            const chosen = r.chosenDecision.some((a: any) => a.type === "obstacle_attack" && a.attackerId === strike.attackerId && equal(a.targetPosition, strike.targetPosition));
            assert.equal(r.labelChoseNativeBarrel, Number(chosen)); assert.equal(r.exactCleanupChosen, equal(r.chosenDecision, r.cleanup));
            assert.equal(r.exactPreCleanupChosen, equal(r.chosenDecision, r.before)); assert.equal(typeof r.rawAndChosenShareArray, "boolean");
            if (r.rawAndChosenShareArray) assert.deepEqual(r.actualRawIncumbent, r.chosenDecision);
            counts[chosen ? "clear" : "other"]++; local[chosen ? "clear" : "other"]++;
            alternatives[r.exactCleanupChosen ? "cleanup" : r.exactPreCleanupChosen ? "before" : "third_action"]++; families.add(r.board);
        });
        assert.deepEqual(local, control.labelCounts);
    }
    assert.equal(ids.size, status.labels); assert.deepEqual(counts, status.labelCounts);
    stages[stage] = { controls, labels, inventory, counts, alternatives, observedFamilies: families.size, observations: ids.size };
}
const a = stages.preflight, b = stages.collection; assert.equal(a.controls.size, 16); assert.equal(b.controls.size, 3024);
let repeats = 0;
for (const [key, r] of a.controls) {
    const full = b.controls.get(key); assert(full);
    for (const k of ["inputSha256", "traceSha256", "score", "actualTurns", "labels", "labelCounts", "labelsSha256"]) assert.deepEqual(full[k], r[k], `cold ${key}/${k}`);
    assert.deepEqual(b.labels.get(key) ?? [], a.labels.get(key) ?? []); repeats += r.labels;
}
assert(repeats > 0);
const primary = json(resolve(p, "primary-analysis.json"));
assert.equal(primary.observations, b.observations); assert.equal(primary.familiesWithObservations, b.observedFamilies);
assert.deepEqual(primary.labelCounts, b.counts); assert.deepEqual(primary.exactActionCategories, b.alternatives);
assert.equal(primary.exactRepeatedObservations, repeats);
assert.deepEqual(primary.inventory, [...a.inventory, ...b.inventory]);
const result = { passed: true, teacherRegistrationSha256: seal, originalStockFights: b.controls.size,
    observations: b.observations, labelCounts: b.counts, exactActionCategories: b.alternatives,
    allProducerLabelPayloadHashesMatch: true, allSourceInputTraceOutcomeAndLabelChecksPassed: true,
    coldCases: a.controls.size, exactRepeatedObservations: repeats, coldObservationParity: true,
    primaryIntegersAndRawInventoryExact: true, newIndependentStrengthSamples: 0, learnerFitted: false };
writeFileSync(resolve(p, "independent-verification.json"), JSON.stringify(result, null, 2) + "\n", { flag: "wx" });
console.log(JSON.stringify(result));

// Explicit public-input allowlist. No choice labels, outcomes, seeds, IDs or case identities enter X.
import assert from "node:assert/strict";
type Cell = { x: number; y: number };
const n = (v: unknown) => typeof v === "number" && Number.isFinite(v) ? v : 0;
const log = (v: number) => Math.log1p(Math.max(0, v));
const distance = (a: Cell[], b: Cell[]) => a.length && b.length ? Math.min(...a.flatMap(x => b.map(y => Math.max(Math.abs(x.x-y.x), Math.abs(x.y-y.y))))) : 16;
const anchor = (cells: Cell[]): Cell => ({ x: Math.max(...cells.map(c => c.x)), y: Math.max(...cells.map(c => c.y)) });
const shifted = (cells: Cell[], destination: Cell): Cell[] => { const a=anchor(cells); return cells.map(c=>({x:c.x+destination.x-a.x,y:c.y+destination.y-a.y})); };
const endpoint = (unit: any, actions: any[]) => {
    const move = actions.find(a => a.type === "move_unit");
    if (move?.targetCells?.length) return move.targetCells as Cell[];
    if (move?.path?.length) return shifted(unit.cells, move.path.at(-1));
    const attack = actions.find(a=>a.type==="obstacle_attack");
    return attack?.attackFrom ? shifted(unit.cells,attack.attackFrom) : unit.cells as Cell[];
};
const pathCost = (path: Cell[]) => path.slice(1).reduce((s,c,i)=>s+Math.hypot(c.x-path[i].x,c.y-path[i].y),0);
const material = (u:any) => n(u.exp)*Math.max(0,n(u.hp))/Math.max(1,n(u.maxHp));
const shooter = (u:any) => n(u.shots)>0&&(n(u.attackSelection)===2||n(u.properties.attack_type)===2);
const damage = (u:any) => Math.max(0,n(u.alive))*Math.max(0,(n(u.properties.attack_damage_min)+n(u.properties.attack_damage_max))/2)*Math.max(0,n(u.properties.attack_multiplier)||1);

export function publicFeatures(observation: any, cellWorldSize=128, maxWorldX=1024) {
    const {unitId, publicState: state, before, cleanup, lap}=observation;
    const actors=state.units.filter((u:any)=>u.id===unitId);assert.equal(actors.length,1);
    const actor=actors[0], props=actor.properties, units=state.units.filter((u:any)=>!u.dead);
    const strike=cleanup.find((a:any)=>a.type==="obstacle_attack");assert(strike);
    const target={x:Math.floor((strike.targetPosition.x+maxWorldX)/cellWorldSize),y:Math.floor(strike.targetPosition.y/cellWorldSize)};
    const barrels=state.barrels.filter((b:any)=>b.cell.x===target.x&&b.cell.y===target.y);assert.equal(barrels.length,1);
    const barrel=barrels[0], current=actor.cells as Cell[], intent=endpoint(actor,before), clear=endpoint(actor,cleanup);
    const own=units.filter((u:any)=>u.team===actor.team&&u.id!==unitId), enemy=units.filter((u:any)=>u.team!==actor.team);
    const features: Record<string,number>={};
    const add=(key:string,value:number|boolean)=>{const v=typeof value==="boolean"?Number(value):value;assert(Number.isFinite(v),key);features[key]=Math.round(Math.max(-8,Math.min(8,v))*1e9)/1e9;};
    add("lap",Math.min(n(lap),32)/16);add("fly",!!actor.fly);add("steps",n(actor.steps)/8);
    add("initiative",n(actor.initiative)/16);add("armor",n(actor.armor)/100);add("rangeArmor",n(actor.rangeArmor)/100);
    add("magicResist",n(props.magic_resist)/100);add("baseAttack",(n(props.base_attack)+n(props.attack_mod))/50);
    add("morale",(n(props.morale)+n(props.morale_mod))/10);add("luck",(n(props.luck)+n(props.luck_mod))/10);
    add("aliveLog",log(n(actor.alive))/8);add("hpLog",log(n(actor.hp))/10);add("materialLog",log(material(actor))/10);
    add("survivingHpFraction",n(actor.hp)/Math.max(1,n(actor.maxHp)*n(actor.alive)));add("damageLog",log(damage(actor))/10);
    add("maxHpLog",log(n(actor.maxHp))/8);add("expLog",log(n(actor.exp))/8);add("width",n(props.footprint_width)/2);add("height",n(props.footprint_height)/2);
    add("canCast",!!props.can_cast_spells);add("remainingSpells",actor.spells.reduce((s:number,x:any)=>s+Number(n(x.remaining)>0),0)/8);
    add("abilities",(props.abilities?.length??0)/8);add("buffs",(props.applied_buffs?.length??0)/8);add("debuffs",(props.applied_debuffs?.length??0)/8);
    add("webLocked",!!props.web_movement_locked);
    for(let i=1;i<=4;i++){add(`faction${i}`,n(props.faction)===i);add(`level${i}`,n(props.level)===i);add(`map${i}`,n(state.gridType)===i);}
    for(const type of ["move_unit","wait_turn","defend_turn"])add(`intent_${type}`,before.some((a:any)=>a.type===type));
    const move=before.find((a:any)=>a.type==="move_unit"), clearPath=strike.path??[];
    add("intentPath",pathCost(move?.path??[])/8);add("clearPath",pathCost(clearPath)/8);
    add("intentLava",!!move?.hasLavaCell);add("intentWater",!!move?.hasWaterCell);add("clearLava",!!strike.hasLavaCell);add("clearWater",!!strike.hasWaterCell);
    add("intentClearDisplacement",distance(intent,clear)/8);add("intentDisplacement",distance(current,intent)/8);add("clearDisplacement",distance(current,clear)/8);
    add("ownBarrel",barrel.team===actor.team);add("barrelCount",state.barrels.length/8);add("ownBarrelCount",state.barrels.filter((b:any)=>b.team===actor.team).length/4);
    add("barrelDistance",distance(current,[target])/8);
    const total=(xs:any[])=>xs.reduce((s,u)=>s+material(u),0), ours=total(own)+material(actor),theirs=total(enemy);
    add("ourMaterialLog",log(ours)/12);add("enemyMaterialLog",log(theirs)/12);add("materialBalance",(ours-theirs)/(ours+theirs+1000));add("actorMaterialShare",material(actor)/(ours+1));
    const queue=state.upNext as string[], actorQueue=queue.indexOf(unitId);add("actorQueueFraction",actorQueue<0?1:actorQueue/Math.max(1,queue.length));
    for(const [side,xs]of [["own",own],["enemy",enemy]]as const){
        const ranged=xs.filter(shooter),casters=xs.filter((u:any)=>u.properties.can_cast_spells);
        add(`${side}_stacks`,xs.length/16);add(`${side}_ranged`,ranged.length/8);add(`${side}_casters`,casters.length/8);add(`${side}_flyers`,xs.filter((u:any)=>u.fly).length/8);
        add(`${side}_rangedMaterialShare`,total(ranged)/(total(xs)+1));
        add(`${side}_meanSteps`,xs.reduce((s:number,u:any)=>s+n(u.steps),0)/Math.max(1,xs.length)/8);
        add(`${side}_readyBeforeActor`,xs.filter((u:any)=>{const i=queue.indexOf(u.id);return i>=0&&actorQueue>=0&&i<actorQueue;}).length/16);
        for(const [position,cells]of [["current",current],["intent",intent],["clear",clear]]as const){
            const ds=xs.map((u:any)=>distance(cells,u.cells));
            add(`${side}_${position}_nearest`,Math.min(16,...ds)/16);
            add(`${side}_${position}_adjacent`,ds.filter((d:number)=>d<=1).length/8);
            add(`${side}_${position}_withinSteps`,ds.filter((d:number)=>d<=n(actor.steps)+1).length/16);
            add(`${side}_${position}_incomingContact`,xs.filter((u:any,i:number)=>!shooter(u)&&ds[i]<=n(u.steps)+1).length/16);
            add(`${side}_${position}_rangedNear`,ranged.filter((u:any)=>distance(cells,u.cells)<=3).length/8);
        }
    }
    for(const [position,cells]of [["intent",intent],["clear",clear]]as const){
        const a=anchor(cells);add(`${position}_forward`,(actor.team===2?a.x:15-a.x)/15);add(`${position}_verticalCenterDistance`,Math.abs(a.y-7.5)/7.5);
        add(`${position}_nearbyBarrels`,state.barrels.filter((b:any)=>distance(cells,[b.cell])<=2).length/8);
        add(`${position}_nearbyTerrain`,state.terrain.filter((c:Cell)=>distance(cells,[c])<=2).length/16);
    }
    return { names:Object.keys(features), values:Object.values(features) };
}

import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { appendFileSync, readFileSync, readdirSync, writeFileSync, mkdirSync } from "node:fs";
import { resolve } from "node:path";
import { gunzipSync } from "node:zlib";
import { publicFeatures } from "./features";
const p=import.meta.dir,data=resolve(process.argv[2]),validation=resolve(process.argv[3]);
const sha=(b:Buffer|string)=>createHash("sha256").update(b).digest("hex");
const prior=JSON.parse(readFileSync(`${validation}/independent-verification.json`,"utf8"));assert(prior.passed&&prior.coldObservationParity&&prior.originalStockFights===3024);
const primary=JSON.parse(readFileSync(`${validation}/primary-analysis.json`,"utf8"));
for(const f of primary.inventory)assert.equal(sha(readFileSync(resolve(data,f.path))),f.sha256);
